FuncDef.Code:
// reference: https://www.geeks3d.com/20141201/how-to-rotate-a-vertex-by-a-quaternion-in-glsl/
void opQuatRotate(inout vec3 p, vec3 axis, float angle)
{
    axis = normalize(axis);

    float halfAngle     = angle * 0.5;
    float sinHalfAngle  = sin(halfAngle);
    float cosHalfAngle  = cos(halfAngle);

    vec4 q = vec4(axis, cosHalfAngle);
    q.xyz *= sinHalfAngle;

    p += 2.0 * cross(q.xyz, cross(q.xyz, p) + q.w * p);
}
